import {createChatOrchestrator} from './chatOrchestrator.js';
import {createMockProvider} from '../providers/mock/mockProvider.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {ChatSession} from '../types/session.js';

it('reports a beforeSession failure before cleanup [specs/hal-engine-config-hooks/spec.md#7]', async () => {
  const error = new Error('setup failed');
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  const calls: string[] = [];
  const orchestrator = createChatOrchestrator(createMockProvider(), new PromptBuilder({identity: 'test'}), undefined, {
    hooks: {
      beforeSession: async () => { throw error; },
      onError: async (receivedSession, receivedError) => {
        if (receivedSession === session && receivedError === error) calls.push('onError');
      },
      afterSession: async () => { calls.push('afterSession'); },
    },
  });

  await expect(orchestrator.processMessage(session)).rejects.toBe(error);
  expect(calls).toEqual(['onError', 'afterSession']);
});
EOF
 timeout 300 node --experimental-vm-modules node_modules/jest/bin/jest.js --runTestsByPath src/orchestration/beforeSessionFailure.test.ts --runInBand"

